import torch
def accumulated_gradient(batches,w0):
    if not batches or any(not xs or len(xs)!=len(ys) for xs,ys in batches):raise ValueError('invalid microbatches')
    total=sum(len(xs) for xs,ys in batches);w=torch.tensor(float(w0),requires_grad=True)
    for xs,ys in batches:
        x=torch.tensor(xs,dtype=torch.float32);y=torch.tensor(ys,dtype=torch.float32)
        (((w*x-y)**2).sum()/total).backward()
    return float(w.grad.item())

