import torch
def next_token_loss(logits,tokens):
    if tokens.shape[1]<2:raise ValueError('need a next token')
    return torch.nn.functional.cross_entropy(logits[:,:-1,:].reshape(-1,logits.shape[-1]),tokens[:,1:].reshape(-1))

