import torch
def weighted_gradient(gradients,counts):
    if not gradients or len(gradients)!=len(counts) or any(type(n) is not int or n<1 for n in counts) or any(g.shape!=gradients[0].shape for g in gradients):raise ValueError('invalid reduction')
    result=torch.zeros_like(gradients[0])
    for gradient,count in zip(gradients,counts):result=result+gradient*count
    return result/sum(counts)

