def merge_lora(base,a,b,alpha):
    if base.ndim!=2 or a.ndim!=2 or b.ndim!=2 or a.shape[0]<1 or a.shape[1]!=base.shape[1] or b.shape!=(base.shape[0],a.shape[0]):raise ValueError('invalid adapter shape')
    return base+(alpha/a.shape[0])*(b@a)

